#include <Cellerator/compiler/ir/planning/implement_complete_cost_vectors_v1.hh>
#include <cmath>
namespace cellerator::compiler::ir::planning::v1 {namespace{constexpr std::size_t ix(cost_dimension_v1 d){return static_cast<std::size_t>(d);}}
complete_cost_status_v1 validate_complete_cost_vector_v1(const complete_cost_vector_v1&v) noexcept{if(!v.reuse_count)return complete_cost_status_v1::invalid_reuse;double sum=0;for(double x:v.nanoseconds){if(!std::isfinite(x)||x<0)return complete_cost_status_v1::invalid_cost;sum+=x;}if(!std::isfinite(v.total_nanoseconds)||std::abs(sum-v.total_nanoseconds)>1e-6*(1+sum))return complete_cost_status_v1::total_mismatch;return complete_cost_status_v1::ok;}
complete_cost_status_v1 import_phase_costs_v1(const cellerator::planner::phase_costs&p,double conversion,double residual,double compile,std::uint64_t reuse,complete_cost_vector_v1*out) noexcept{if(!out||!reuse)return complete_cost_status_v1::invalid_reuse;complete_cost_vector_v1 v{};v.reuse_count=reuse;v.nanoseconds[ix(cost_dimension_v1::preparation)]=(p.host_preparation_ns+p.projection_construction_ns+p.backend_prepare_ns)/reuse;v.nanoseconds[ix(cost_dimension_v1::conversion)]=conversion/reuse;v.nanoseconds[ix(cost_dimension_v1::transfer)]=p.h2d_ns+p.d2h_ns;v.nanoseconds[ix(cost_dimension_v1::pack)]=p.semantic_packing_ns/reuse+p.static_value_pack_ns/reuse+p.dynamic_input_pack_ns;v.nanoseconds[ix(cost_dimension_v1::order)]=p.order_transform_ns;v.nanoseconds[ix(cost_dimension_v1::execution)]=p.kernel_ns;v.nanoseconds[ix(cost_dimension_v1::residual)]=residual;v.nanoseconds[ix(cost_dimension_v1::epilogue)]=p.epilogue_ns;v.nanoseconds[ix(cost_dimension_v1::synchronization)]=p.synchronization_ns;v.nanoseconds[ix(cost_dimension_v1::canonicalization)]=0;v.nanoseconds[ix(cost_dimension_v1::memory)]=0;v.nanoseconds[ix(cost_dimension_v1::compile_time)]=compile/reuse;v.nanoseconds[ix(cost_dimension_v1::reuse_amortization)]=0;v.nanoseconds[ix(cost_dimension_v1::communication)]=p.communication_ns;v.persistent_bytes=p.persistent_bytes;v.transient_bytes=p.transient_bytes;for(double x:v.nanoseconds)v.total_nanoseconds+=x;auto s=validate_complete_cost_vector_v1(v);if(s==complete_cost_status_v1::ok)*out=v;return s;}
}
